package com.StudentManagementwithloginlogout.StudentManagementwithloginlogout.config;
import java.io.IOException; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import jakarta.servlet.FilterChain; import jakarta.servlet.ServletException; import jakarta.servlet.http.*; import com.StudentManagementwithloginlogout.StudentManagementwithloginlogout.entity.*;
@Component public class SessionAuthFilter extends OncePerRequestFilter { protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException {String p=req.getRequestURI(); if(p.startsWith("/css/")||p.startsWith("/js/")||p.startsWith("/login")||p.startsWith("/register")||p.startsWith("/api/auth/")||p.equals("/home")||p.equals("/")||p.equals("/error")){chain.doFilter(req,res);return;} Object o=req.getSession(false)==null?null:req.getSession(false).getAttribute("loggedUser"); if(!(o instanceof User)){if(p.startsWith("/api/")){res.setStatus(401);res.setContentType("application/json");res.getWriter().write("{\"error\":\"Authentication required\"}");}else res.sendRedirect("/login");return;} User u=(User)o; if((p.startsWith("/api/audit")||(p.contains("/modifications/")&&(p.contains("/approve")||p.contains("/reject")||p.endsWith("/pending"))))&&u.getRole()!=Role.ADMIN){if(p.startsWith("/api/")){res.setStatus(403);res.getWriter().write("{\"error\":\"Admin access required\"}");}else res.sendError(403);return;} chain.doFilter(req,res);}}
